(() => {
  const tz = 'America/Montevideo';
  const raw = $json.Fecha_de_recepcion_del_pago;

  // La Data Table entrega campos dateTime como Luxon DateTime, no como string.
  // Detectar tipo y usar el constructor adecuado.
  let dt;
  if (raw && typeof raw === 'object' && raw.isLuxonDateTime) {
    dt = raw.setZone(tz);
  } else if (raw instanceof Date) {
    dt = DateTime.fromJSDate(raw).setZone(tz);
  } else {
    dt = DateTime.fromISO(String(raw ?? ''), { zone: tz });
  }
  dt = dt.startOf('day');

  if (!dt.isValid) return null;

  const jan1 = dt.startOf('year');
  const daysToFirstSunday = (7 - jan1.weekday) % 7;
  const firstSunday = jan1.plus({ days: daysToFirstSunday });

  if (dt <= firstSunday) return 'S1';

  const firstMonday = firstSunday.plus({ days: 1 });
  const diffDays = Math.floor(dt.diff(firstMonday, 'days').days);
  const week = 2 + Math.floor(diffDays / 7);
  return 'S' + week;
})()
}}

